part("angle","rt",{"cx":300,"cy":370,"r":240,"a1":0,"a2":90,"color":RD,"fill":"#FFCDD2","arc":70})
part("raw","rsq",{"kind":"path","d":"M300 320 L350 320 L350 370","stroke":RD,"width":4})
L("A right angle looks like the letter L","tRt1",y=420,size=30,color=RD); L("A straight angle holds two right angles","tRt2",y=200,size=28,color="#1F3B6E",x=650)
L("Lines that meet at a right angle are perpendicular","tPerp",y=475,size=28,color=GR)
part("angle","ac",{"cx":120,"cy":330,"r":150,"a1":0,"a2":40,"color":GR,"fill":"#C8E6C9","arc":50})
part("angle","rg",{"cx":370,"cy":330,"r":150,"a1":0,"a2":90,"color":RD,"fill":"#FFCDD2","arc":50})
