L("360° ÷ 4 = 90°      360° ÷ 6 = 60°      360° ÷ 8 = 45°","tSplit",y=60,size=28,color="#1F3B6E"); L("360° ÷ 3 = 120°      360° ÷ 5 = 72°      360° ÷ 12 = 30°","tSplit2",y=480,size=28,color="#1F3B6E")
L("The Rigveda mentions a wheel with 360 spokes","tWhy",y=120,size=30,color=GR); L("Old calendars of India, Persia, Babylon and Egypt had 360 days","tWhy2",y=200,size=28,color=GR); L("360 divides evenly by 1 to 10 (except 7), 12 and 24","tWhy3",y=280,size=30,color=GR); L("So it is easy to split a circle into equal parts","tWhy4",y=360,size=30,color=OR)
part("protractor","pr",{"cx":450,"cy":370,"r":300})
part("angle","pa",{"cx":450,"cy":370,"r":290,"a1":0,"a2":60,"color":RD,"fill":"#FFCDD2","arc":130,"label":"60°"})
