# --- clocks
def clk(pre,cx,cy,hr,col):
    C_=part("raw",pre+"f",{"kind":"circle","cx":cx,"cy":cy,"r":78,"fill":"#FFFFFF","stroke":"#16253F","width":4})
    for k in range(12):
        x1,y1=pol(cx,cy,78,k*30); x2,y2=pol(cx,cy,66,k*30); SEG(f"{pre}t{k}",x1,y1,x2,y2,"#16253F",3)
    x,y=pol(cx,cy,50,90-30*hr); SEG(pre+"h",cx,cy,x,y,col,7)
    x,y=pol(cx,cy,68,90); SEG(pre+"m",cx,cy,x,y,"#16253F",4)
    ARC(pre+"a",cx,cy,26,90-30*hr if hr<=6 else 90,90 if hr<=6 else 90-30*hr+0,col,5) if hr<=6 else None
    L(f"{hr} o'clock",pre+"l",y=cy+108,size=22,color=col,x=cx); L(f"{30*hr}°",pre+"d",y=cy+138,size=26,color=col,x=cx)
