for k in range(9):
    x,y=pol(300,300,210,-90+k*22.5); ARR("eq%d"%k,300,300,x,y,"#1E88E5" if k%2==0 else "#2E7D32",4)
ARC("eqa",300,300,190,-90,90,"#E65100",4); L("180° ÷ 8 = 22.5° each","eqT",y=60,size=26,color="#1E5FA8",x=620); L("Bisecting three times: 90°, 45°, 22.5°","eqU",y=455,size=20,color="#C0392B",x=620)
step("x7-eight",X7,"A straight angle of 180 degrees is divided into eight equal angles. Each one is 180 divided by 8, which is 22.5 degrees. You can also get this by folding: fold the straight angle in half to get 90 degrees, in half again for 45, and once more for 22.5. Cutting an angle into two equal halves is called bisecting it, and the line that does it is the angle bisector.","180° நேர்கோணம் எட்டுச் சம கோணங்களாகப் பிரிக்கப்பட்டுள்ளது. ஒவ்வொன்றும் 180 ÷ 8 = 22.5°. மடித்தும் பெறலாம்: நேர்கோணத்தை மடித்தால் 90°, மீண்டும் 45°, இன்னொரு முறை 22.5°. ஒரு கோணத்தைச் சம பாதிகளாகப் பிரிப்பது இருசமவெட்டு, அதைச் செய்யும் கோடு கோண இருசமவெட்டி.",[["clear","","",{}]]+wr(["eqT"],0.02,0)+sh(["eqa"],0.08,0)+sh(["eq%d"%k for k in range(9)],0.15,0.07)+wr(["eqU"],0.85,0))
qs("x7-q5",X7,"If the straight angle is divided into 8 equal angles, each angle is:","நேர்கோணம் 8 சம கோணங்களாகப் பிரிக்கப்பட்டால் ஒவ்வொன்றும்:","180° ÷ 8:","180° ÷ 8:",0,[O("22.5°","22.5°"),O("45°","45°","45° is 180° ÷ 4.","45° என்பது 180° ÷ 4."),O("20°","20°","20 × 8 is only 160.","20 × 8 = 160 மட்டுமே.")],"180 ÷ 8 = 22.5.","180 ÷ 8 = 22.5.")

