step("x9-slab",X9,"A toy has slanting slabs, and balls roll down them. The slope of each slab can be described by an angle. The vertex is where the slab meets the ground. One arm is the ground, which is a horizontal line you may not notice. The other arm is the edge of the slab, which you can see. The bigger the angle, the steeper the slab, and the faster the ball rolls.","ஒரு பொம்மையில் சாய்வுத் தட்டுகள்; பந்துகள் உருண்டு வரும். ஒவ்வொரு தட்டின் சாய்வையும் கோணத்தால் சொல்லலாம். தட்டு தரையைத் தொடும் இடம் முனை. ஒரு கை தரை (கிடைமட்டக் கோடு), மற்றொன்று தட்டின் விளிம்பு. கோணம் பெரியதெனில் சாய்வு அதிகம், பந்து வேகமாக உருளும்.",[CL]+sh(["slg","sls","slv"],0.05,0.1)+sh(["sla"],0.45,0.05,"show",500)+wr(["slT","slG","slS","slV"],0.6,0.1))
qs("x9-q3",X9,"In the slab toy, which angle makes the ball roll faster?","சாய்வுத் தட்டு பொம்மையில் எந்தக் கோணம் பந்தை வேகமாக உருளச் செய்யும்?","Think about steepness:","செங்குத்துத் தன்மையை எண்ணுங்கள்:",2,[O("A smaller angle","சிறிய கோணம்","A smaller angle is a gentler slope.","சிறிய கோணம் மெதுவான சாய்வு."),O("The same speed for all angles","எல்லாக் கோணத்துக்கும் ஒரே வேகம்","The slope changes the speed.","சாய்வு வேகத்தை மாற்றும்."),O("A bigger angle","பெரிய கோணம்")],"A bigger angle means a steeper slab.","பெரிய கோணம் என்றால் செங்குத்தான தட்டு.")

X10="X10 Dot grid angles"
def gridpts(pre,x0,y0,sp=48):
    for r in range(7):
        for c in range(7): part("raw","%sd%d%d"%(pre,r,c),{"kind":"circle","cx":x0+c*sp,"cy":y0+r*sp,"r":5,"fill":"#16253F","stroke":"#16253F","width":1})
def gp(x0,y0,c,r,sp=48): return (x0+c*sp,y0+r*sp)
GX=[(60,110),(500,110)]
CFG={"s":[((3,2),(6,2),[(0,2),(1,2),(2,2)]),((2,2),(4,4),[(1,1),(0,0)])],
     "r":[((3,2),(6,2),[(3,0),(3,1),(3,3),(3,4),(3,5),(3,6)]),((2,2),(4,4),[(3,1),(4,0),(1,3),(0,4)])]}
for kind,nm in (("s","st"),("r","rt")):
    for gi,(A,B,pts) in enumerate(CFG[kind]):
        x0,y0=GX[gi]
        if kind=="s": gridpts("st%d"%gi,x0,y0)
        ax,ay=gp(x0,y0,*A); bx,by=gp(x0,y0,*B)
        SEG("%s%dab"%(nm,gi),ax,ay,bx,by,"#C0392B",6)
        L("A","%s%dA"%(nm,gi),y=ay-14,size=22,color="#C0392B",x=ax); L("B","%s%dB"%(nm,gi),y=by-14,size=22,color="#C0392B",x=bx)
        for k,(c,r) in enumerate(pts):
            px,py=gp(x0,y0,c,r); SEG("%s%dp%d"%(nm,gi,k),ax,ay,px,py,"#2E7D32",5)
L("Join A to other grid points to get a straight angle","stT",y=60,size=24,color="#1E5FA8")
L("Join A to other grid points to get a right angle","rtT",y=60,size=24,color="#1E5FA8")
L("Left: all 3 points on the row, to the left of A.   Right: the 2 points on the same diagonal, beyond A.","stU",y=470,size=18,color="#2E7D32")
L("Left: 6 points in the column through A.   Right: 4 points along the other diagonal through A.","rtU",y=470,size=18,color="#2E7D32")
def gdo(nm,kind):
    ids=[]
    for gi in (0,1):
        ids+=["%s%dd%d%d"%(nm,gi,r,c) for r in range(7) for c in range(7)]
    return ids
step("x10-straight",X10,"Here are two dot grids. In each, A and B are joined. To make a straight angle at A, the new arm must point exactly opposite to A B, so that the two arms form one straight line through A. On the left, A B goes right along a row, so the points to the left of A on the same row all work: three ways. On the right, A B goes down along a diagonal, so the points up on the same diagonal beyond A work: two ways.","இரு புள்ளிக் கட்டங்கள். ஒவ்வொன்றிலும் A, B இணைக்கப்பட்டுள்ளது. A இல் நேர்கோணம் பெற புதிய கை AB க்கு நேர் எதிர்த் திசையில் இருக்க வேண்டும். இடப்புறம் AB வலப்புறம் செல்கிறது; A க்கு இடப்பக்கம் அதே வரிசையில் உள்ள மூன்று புள்ளிகளும் சரி. வலப்புறம் AB கீழ் நோக்கிய மூலைவிட்டம்; அதே மூலைவிட்டத்தில் A க்கு மேல் உள்ள இரு புள்ளிகள் சரி.",[CL]+wr(["stT"],0.02,0)+sh(gdo("st",0),0.06,0.001,"show",150)+sh(["st0ab","st0A","st0B","st1ab","st1A","st1B"],0.4,0.03)+sh(["st0p0","st0p1","st0p2","st1p0","st1p1"],0.55,0.07,"show",300)+wr(["stU"],0.95,0))
step("x10-right",X10,"Now a right angle at A. The new arm must be perpendicular to A B. On the left, A B is along a row, so the arm must go straight up or straight down along the column through A: six points work. On the right, A B goes down along a diagonal, so a right angle needs the other diagonal through A: four points work, two on each side of A.","இப்போது A இல் செங்கோணம். புதிய கை AB க்குச் செங்குத்தாக இருக்க வேண்டும். இடப்புறம் AB வரிசை வழியே; எனவே A வழியாகச் செல்லும் நெடுவரிசையில் மேலும் கீழும் ஆறு புள்ளிகள் சரி. வலப்புறம் AB மூலைவிட்டம்; A வழியே மற்றொரு மூலைவிட்டத்தில் நான்கு புள்ளிகள் சரி, A இன் இருபுறமும் இரண்டு.",[CL]+wr(["rtT"],0.02,0)+sh(gdo("st",0),0.06,0.001,"show",150)+sh(["rt0ab","rt0A","rt0B","rt1ab","rt1A","rt1B"],0.4,0.03)+sh(["rt0p%d"%k for k in range(6)]+["rt1p%d"%k for k in range(4)],0.55,0.04,"show",300)+wr(["rtU"],0.95,0))
qs("x10-q1",X10,"On the left grid, how many grid points can A be joined to so that the angle at A is a right angle?","இடப்புறக் கட்டத்தில் A இல் செங்கோணம் அமைய A ஐ எத்தனை புள்ளிகளுடன் இணைக்கலாம்?","A B is along a row. The other arm must be along the column:","AB வரிசை வழியே. மற்றொரு கை நெடுவரிசை வழியே:",2,[O("3","3","3 is for the straight angle, on the row.","3 என்பது நேர்கோணத்துக்கு, வரிசையில்."),O("4","4","4 is for the right angle on the diagonal grid.","4 என்பது மூலைவிட்டக் கட்டத்துக்கு."),O("6","6")],"The column through A has 6 other points: 2 above and 4 below.","நெடுவரிசையில் 6 புள்ளிகள் உள்ளன.")
qs("x10-q2",X10,"On the right grid, why can we join A to only 2 points for a straight angle?","வலப்புறக் கட்டத்தில் நேர்கோணத்துக்கு A ஐ 2 புள்ளிகளுடன் மட்டுமே ஏன் இணைக்கலாம்?","The new arm must be opposite A B:","புதிய கை AB க்கு எதிர்த்திசையில்:",1,[O("Only 2 points are on the grid","கட்டத்தில் 2 புள்ளிகள் மட்டுமே உள்ளன","The grid has many points; the line limits them.","கட்டத்தில் பல புள்ளிகள் உள்ளன; கோடு அவற்றைக் குறைக்கிறது."),O("Only 2 points lie on the diagonal beyond A","A க்கு அப்பால் மூலைவிட்டத்தில் 2 புள்ளிகள் மட்டுமே"),O("A straight angle needs 2 arms","நேர்கோணத்துக்கு 2 கைகள் வேண்டும்","That is true but does not limit the points.","அது உண்மை; ஆனால் புள்ளிகளைக் குறைக்காது.")],"The line through A and B ends at the grid edge after 2 more points.","A, B வழிக்கோடு 2 புள்ளிகளுக்குப் பிறகு கட்டத்தின் விளிம்பை அடைகிறது.")
# nested triangles: acute angles 3, 12, 21, 30, next 39
def TRN(pre,cx,top,sz,k):
    # k levels of nesting
    import math
    h=sz*0.866
    A=[cx,top];B=[cx-sz/2,top+h];C=[cx+sz/2,top+h]
    part("raw",pre+"0",{"kind":"poly","points":[A,B,C],"fill":"#FFFFFF","stroke":"#16253F","width":4})
    if k>=1:
        m=lambda P,Q:[(P[0]+Q[0])/2,(P[1]+Q[1])/2]
        D,E,F=m(B,C),m(A,C),m(A,B)
        part("raw",pre+"1",{"kind":"poly","points":[D,E,F],"fill":"#BBDEFB","stroke":"#16253F","width":3})
    if k>=2:
        G=[ (D[0]+E[0])/2,(D[1]+E[1])/2];Hh=[(E[0]+F[0])/2,(E[1]+F[1])/2];Ii=[(D[0]+F[0])/2,(D[1]+F[1])/2]
        part("raw",pre+"2",{"kind":"poly","points":[G,Hh,Ii],"fill":"#FFE0B2","stroke":"#16253F","width":3})
TRN("na",150,120,220,0); TRN("nb",450,120,220,1); TRN("nc",750,120,220,2)
for i,(t,c) in enumerate([("3 acute angles","#2E7D32"),("12 acute angles","#E65100"),("21 acute angles","#C0392B")]): L(t,"nt%d"%i,y=400,size=22,color=c,x=150+i*300)
L("Count the acute angles: 3, 12, 21, then 30, 39, ... (add 9 each time)","ntT",y=60,size=22,color="#1E5FA8"); L("Next figure: 30 acute angles","ntN",y=455,size=24,color="#C0392B")
step("x10-tri",X10,"Count the acute angles in each figure. The single equilateral triangle has 3. Join the middle points of its sides, and we get 4 small triangles, 12 acute angles in all. Do it again inside the middle triangle, and the count is 21. The numbers 3, 12, 21 go up by 9 each time, so the next figure will have 30, and then 39.","ஒவ்வொரு படத்திலும் குறுங்கோணங்களை எண்ணுங்கள். ஒரு சமபக்க முக்கோணம்: 3. பக்கங்களின் நடுப்புள்ளிகளை இணைத்தால் 4 சிறிய முக்கோணங்கள்: மொத்தம் 12. நடு முக்கோணத்துக்குள் மீண்டும் செய்தால் 21. 3, 12, 21 ஒவ்வொரு முறையும் 9 கூடுகிறது; அடுத்த படத்தில் 30, பிறகு 39.",[CL]+wr(["ntT"],0.02,0)+sh(["na0","nt0"],0.1,0.1)+sh(["nb0","nb1","nt1"],0.35,0.1)+sh(["nc0","nc1","nc2","nt2"],0.6,0.1)+wr(["ntN"],0.9,0))
qs("x10-q3",X10,"The acute angle counts are 3, 12, 21, … What is the number in the next figure?","குறுங்கோணங்களின் எண்ணிக்கை 3, 12, 21, … அடுத்த படத்தில் எத்தனை?","The count goes up by 9 each time:","ஒவ்வொரு முறையும் 9 கூடுகிறது:",0,[O("30","30"),O("27","27","The gap is 9: 21 + 9 = 30.","இடைவெளி 9: 21 + 9 = 30."),O("33","33","The gap is 9, not 12.","இடைவெளி 9, 12 அல்ல.")],"21 + 9 = 30.","21 + 9 = 30.")

